namespace ghidra.app.plugin.core.symboltree.actions;

using ghidra.app.context;
using ghidra.app.context;
using ghidra.program.model.listing;
using ghidra.program.model.symbol;
using ghidra.util;
using docking.action;

public class ClearPinSymbolAction : ProgramSymbolContextAction {

	public ClearPinSymbolAction(string owner, string popupGroup) : base("Clear Pinned Symbol", owner)
    {
		setPopupMenuData(new MenuData(new string[] { "Clear Pinned Symbol(s)" }, popupGroup));
		setDescription("Unpins symbol(s) so that the symbol moves with memory block moves or image base changes.");
		setHelpLocation(new HelpLocation("SymbolTablePlugin", "Pinning a Symbol"));
	}

	/* @Override */
	protected void actionPerformed(ProgramSymbolActionContext context) {
		Program program = context.getProgram();
		int transactionID = program.startTransaction("Clear Pinned");
		try {
			foreach (Symbol symbol in context.getSymbols()) {
				if (symbol.isPinned()) {
					symbol.setPinned(false);
				}
			}
		}
		finally {
			program.endTransaction(transactionID, true);
		}
	}

	/* @Override */
	protected bool isEnabledForContext(ProgramSymbolActionContext context) {
		foreach (Symbol symbol in context.getSymbols()) {
			if (symbol.isPinned()) {
				return true;
			}
		}
		return false;
	}

}
